"use client";

import React, { useState, useEffect } from "react";
import axios from "axios";
import { API_BASE, API_HOST } from "@/lib/api";
import { getAndClearReturnUrl } from "@/lib/returnUrl";
import { 
  Smartphone, 
  ShieldCheck, 
  CheckCircle2, 
  ArrowRight, 
  Loader2, 
  LogOut, 
  AlertCircle, 
  RotateCw,
  Lock,
  TrainFront
} from "lucide-react";

export default function VerifyMobileOnboardingPage() {
  const [mounted, setMounted] = useState(false);
  const [user, setUser] = useState<any>(null);
  const [mobileNumber, setMobileNumber] = useState("");
  const [otp, setOtp] = useState("");
  const [step, setStep] = useState<"number" | "otp" | "success">("number");
  const [countdown, setCountdown] = useState(0);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);

  useEffect(() => {
    setMounted(true);
    try {
      const stored = localStorage.getItem("user");
      const token = localStorage.getItem("accessToken");
      if (!stored || !token) {
        window.location.href = "/login";
        return;
      }
      const parsed = JSON.parse(stored);
      setUser(parsed);

      // If user is already verified, bypass onboarding immediately
      if (parsed.mobileVerified === true || parsed.mobileVerification?.verified === true) {
        window.location.href = getAndClearReturnUrl();
        return;
      }

      // Pre-fill existing mobile number if present
      if (parsed.mobileNumber) {
        // Strip country code for the 10-digit input field
        const clean = parsed.mobileNumber.replace(/^(\+91|91)/, "").replace(/\D/g, "");
        if (clean.length === 10) {
          setMobileNumber(clean);
        }
      }
    } catch {
      window.location.href = "/login";
    }
  }, []);

  // Cooldown timer
  useEffect(() => {
    if (countdown > 0) {
      const timer = setTimeout(() => setCountdown(c => c - 1), 1000);
      return () => clearTimeout(timer);
    }
  }, [countdown]);

  const handleSendOtp = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    const cleanNumber = mobileNumber.replace(/\D/g, "");
    if (!cleanNumber || !/^[6-9]\d{9}$/.test(cleanNumber)) {
      setError("Please enter a valid 10-digit Indian mobile number starting with 6, 7, 8, or 9.");
      return;
    }

    setLoading(true);
    setError(null);
    setSuccessMsg(null);

    try {
      const token = localStorage.getItem("accessToken");
      const normalizedMobile = `+91${cleanNumber}`;

      const res = await axios.post(
        `${API_BASE}/auth/mobile/send-otp`,
        { mobileNumber: normalizedMobile },
        {
          headers: {
            "Content-Type": "application/json",
            ...(token ? { Authorization: `Bearer ${token}` } : {})
          },
          withCredentials: true
        }
      );

      if (res.data.success) {
        setStep("otp");
        setCountdown(60);
        setSuccessMsg(res.data.message || "OTP code sent successfully!");
      }
    } catch (err: any) {
      setError(err.response?.data?.error || err.response?.data?.message || "Failed to send OTP. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const handleVerifyOtp = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    const cleanOtp = otp.trim();
    if (!cleanOtp || cleanOtp.length !== 6 || !/^\d{6}$/.test(cleanOtp)) {
      setError("Please enter a valid 6-digit OTP code.");
      return;
    }

    setLoading(true);
    setError(null);
    setSuccessMsg(null);

    try {
      const token = localStorage.getItem("accessToken");
      const res = await axios.post(
        `${API_BASE}/auth/mobile/verify-otp`,
        { otpCode: cleanOtp },
        {
          headers: {
            "Content-Type": "application/json",
            ...(token ? { Authorization: `Bearer ${token}` } : {})
          },
          withCredentials: true
        }
      );

      if (res.data.success) {
        // Update user in localStorage
        try {
          const stored = localStorage.getItem("user");
          const u = stored ? JSON.parse(stored) : {};
          u.mobileVerified = true;
          u.mobileNumber = res.data.data?.mobileNumber || `+91${mobileNumber.replace(/\D/g, "")}`;
          u.mobileVerifiedAt = res.data.data?.mobileVerifiedAt || new Date().toISOString();
          if (!u.mobileVerification) u.mobileVerification = {};
          u.mobileVerification.verified = true;
          localStorage.setItem("user", JSON.stringify(u));
        } catch {}

        setStep("success");
        setSuccessMsg("Mobile number verified successfully!");

        // Redirect to intended destination or home
        setTimeout(() => {
          const target = getAndClearReturnUrl();
          window.location.href = target;
        }, 1200);
      }
    } catch (err: any) {
      setError(err.response?.data?.error || err.response?.data?.message || "Invalid or expired OTP. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const handleSignOut = () => {
    try {
      localStorage.removeItem("user");
      localStorage.removeItem("accessToken");
      localStorage.removeItem("refreshToken");
    } catch {}
    window.location.href = "/login";
  };

  if (!mounted) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background">
        <Loader2 className="w-8 h-8 text-primary animate-spin" />
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 md:p-8 bg-background selection:bg-rose-500/30">
      <div className="w-full max-w-md bg-card border border-subtle rounded-3xl p-6 md:p-8 shadow-2xl backdrop-blur-xl relative overflow-hidden">
        {/* Glow decorative backdrop */}
        <div className="absolute -top-24 -right-24 w-60 h-60 bg-blue-500/10 rounded-full blur-3xl pointer-events-none" />
        <div className="absolute -bottom-24 -left-24 w-60 h-60 bg-emerald-500/10 rounded-full blur-3xl pointer-events-none" />

        {/* Brand header */}
        <div className="flex flex-col items-center text-center mb-6">
          <div className="p-3 bg-blue-500/10 border border-blue-500/20 rounded-2xl mb-3 text-blue-600 dark:text-blue-400">
            <TrainFront className="w-7 h-7" />
          </div>
          <div className="flex items-center gap-1.5 px-3 py-1 rounded-full bg-blue-500/10 border border-blue-500/20 text-blue-500 text-[11px] font-bold uppercase tracking-wider mb-2">
            <ShieldCheck className="w-3.5 h-3.5" />
            <span>Account Security Onboarding</span>
          </div>
          <h1 className="text-2xl font-display font-black tracking-tight text-main">
            Verify Mobile Number
          </h1>
          <p className="text-xs text-muted mt-1.5 max-w-xs">
            Mandatory for new accounts to secure your bookings, passenger identity, and train updates.
          </p>
          {user?.email && (
            <p className="text-[11px] font-medium text-main/80 mt-2 px-2.5 py-0.5 rounded-md bg-surface border border-subtle">
              Signed in as <span className="font-semibold text-primary">{user.email}</span>
            </p>
          )}
        </div>

        {/* Error notification */}
        {error && (
          <div className="mb-4 p-3 rounded-xl bg-red-500/10 border border-red-500/30 text-red-500 text-xs flex items-start gap-2 animate-shake">
            <AlertCircle className="w-4 h-4 shrink-0 mt-0.5" />
            <span>{error}</span>
          </div>
        )}

        {/* Success notification */}
        {successMsg && (
          <div className="mb-4 p-3 rounded-xl bg-emerald-500/10 border border-emerald-500/30 text-emerald-500 text-xs flex items-start gap-2">
            <CheckCircle2 className="w-4 h-4 shrink-0 mt-0.5" />
            <span>{successMsg}</span>
          </div>
        )}

        {/* STEP 1: Phone number entry */}
        {step === "number" && (
          <form onSubmit={handleSendOtp} className="space-y-4">
            <div>
              <label className="block text-xs font-bold text-main mb-1.5">
                Indian Mobile Number
              </label>
              <div className="flex rounded-xl overflow-hidden border border-subtle focus-within:border-blue-500 focus-within:ring-2 focus-within:ring-blue-500/30 transition-all bg-input">
                <span className="px-3 py-3 bg-surface/50 text-main font-bold text-sm border-r border-subtle flex items-center select-none">
                  🇮🇳 +91
                </span>
                <input
                  type="tel"
                  inputMode="numeric"
                  maxLength={10}
                  value={mobileNumber}
                  onChange={(e) => {
                    const val = e.target.value.replace(/\D/g, "");
                    setMobileNumber(val);
                    if (error) setError(null);
                  }}
                  placeholder="9876543210"
                  className="w-full px-3 py-3 bg-transparent text-main font-medium text-sm focus:outline-none placeholder:text-muted/60"
                  autoFocus
                />
              </div>
              <p className="text-[11px] text-muted mt-1.5">
                A 6-digit verification code will be sent to this number.
              </p>
            </div>

            <button
              type="submit"
              disabled={loading || mobileNumber.length !== 10}
              className="w-full py-3.5 px-4 rounded-xl bg-blue-600 hover:bg-blue-700 active:bg-blue-800 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold text-sm flex items-center justify-center gap-2 shadow-lg shadow-blue-500/20 transition-all cursor-pointer"
            >
              {loading ? (
                <>
                  <Loader2 className="w-4 h-4 animate-spin" />
                  <span>Sending Code...</span>
                </>
              ) : (
                <>
                  <span>Send Verification Code</span>
                  <ArrowRight className="w-4 h-4" />
                </>
              )}
            </button>
          </form>
        )}

        {/* STEP 2: OTP verification */}
        {step === "otp" && (
          <form onSubmit={handleVerifyOtp} className="space-y-4">
            <div className="p-3 rounded-xl bg-surface border border-subtle flex items-center justify-between">
              <div>
                <span className="text-[11px] text-muted block">Code sent to</span>
                <span className="text-xs font-bold text-main">+91 {mobileNumber}</span>
              </div>
              <button
                type="button"
                onClick={() => {
                  setStep("number");
                  setOtp("");
                  setError(null);
                }}
                className="text-xs font-semibold text-blue-500 hover:underline cursor-pointer"
              >
                Change Number
              </button>
            </div>

            <div>
              <label className="block text-xs font-bold text-main mb-1.5 text-center">
                Enter 6-Digit OTP
              </label>
              <input
                type="text"
                inputMode="numeric"
                maxLength={6}
                value={otp}
                onChange={(e) => {
                  const val = e.target.value.replace(/\D/g, "");
                  setOtp(val);
                  if (error) setError(null);
                }}
                placeholder="••••••"
                className="w-full px-4 py-3.5 bg-input border border-subtle rounded-xl text-center text-xl font-bold tracking-[0.4em] text-main focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/30 transition-all"
                autoFocus
              />
            </div>

            <button
              type="submit"
              disabled={loading || otp.length !== 6}
              className="w-full py-3.5 px-4 rounded-xl bg-emerald-600 hover:bg-emerald-700 active:bg-emerald-800 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold text-sm flex items-center justify-center gap-2 shadow-lg shadow-emerald-500/20 transition-all cursor-pointer"
            >
              {loading ? (
                <>
                  <Loader2 className="w-4 h-4 animate-spin" />
                  <span>Verifying...</span>
                </>
              ) : (
                <>
                  <ShieldCheck className="w-4 h-4" />
                  <span>Verify &amp; Continue</span>
                </>
              )}
            </button>

            {/* Resend OTP button */}
            <div className="text-center pt-1">
              {countdown > 0 ? (
                <p className="text-xs text-muted">
                  Resend code in <span className="font-bold text-main">{countdown}s</span>
                </p>
              ) : (
                <button
                  type="button"
                  onClick={() => handleSendOtp()}
                  disabled={loading}
                  className="text-xs font-bold text-blue-500 hover:underline inline-flex items-center gap-1 cursor-pointer"
                >
                  <RotateCw className="w-3 h-3" />
                  <span>Resend Verification Code</span>
                </button>
              )}
            </div>
          </form>
        )}

        {/* STEP 3: Verification success */}
        {step === "success" && (
          <div className="py-6 flex flex-col items-center text-center space-y-3 animate-scale-up">
            <div className="p-3.5 bg-emerald-500/20 text-emerald-500 rounded-full">
              <CheckCircle2 className="w-10 h-10" />
            </div>
            <h2 className="text-lg font-bold text-main">Verification Complete!</h2>
            <p className="text-xs text-muted">Redirecting you to Trayago...</p>
            <Loader2 className="w-5 h-5 text-primary animate-spin mt-2" />
          </div>
        )}

        {/* Footer actions: Sign out escape hatch */}
        <div className="mt-6 pt-4 border-t border-subtle flex items-center justify-between text-xs text-muted">
          <span className="flex items-center gap-1 text-[11px]">
            <Lock className="w-3 h-3 text-muted" />
            IRCTC Booking Security Policy
          </span>
          <button
            type="button"
            onClick={handleSignOut}
            className="text-muted hover:text-red-500 transition-colors flex items-center gap-1 text-[11px] cursor-pointer"
            title="Sign out to use a different account"
          >
            <LogOut className="w-3 h-3" />
            <span>Sign Out</span>
          </button>
        </div>
      </div>
    </div>
  );
}
